head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.disFlag ="";

// var gAfStdIndCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — setComboCode, readSync, initForm, changeForm 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {

        const pPrams = $c.data.getParameter();

        scwin.disFlag =  $c.data.getParameter("disFlag");

        let newSecugrpid = "";

        if(scwin.disFlag === "C") {
            newSecugrpid  = $c.win.getParent().sbx_NEW_SECUGRP_ID.getValue();
        } else {
            newSecugrpid =  $c.data.getParameter("secugrpId");
        }

        if( newSecugrpid !== "ST" ) {
            grp_Forn_Item.show();
        } else {
            grp_Forn_Item.hide();
        }

        await scwin.setComboCode(); // 셀렉트박스

        scwin.vBzProcsNo = pPrams.bzProcsNo;
        scwin.mktTpCd = $c.win.getParent().scwin.mktTpCd;

        if ( scwin.vBzProcsNo !== "" && scwin.vBzProcsNo !== undefined) { // 수정
            // fn_initForm("");
            await scwin.readSync();
            cmb_SECUGRP_ID.Enable2 = false;
        } else { // 등록
            scwin.initForm("C");

            cmb_SECUGRP_ID.setValue(newSecugrpid);

        }
        scwin.changeForm("01"); // 초기값-심사진행
        // $c.win.alert( '[cmb_SECUGRP_ID]'+getObjectValue(cmb_SECUGRP_ID));

        // 컴포넌트 객체 전달
        $c.date.checkCalendarFormat("edt_INVSTG_BILL_ACPT_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("ica_listDd", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_LIST_DELIB_SCHDL_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_LIST_DELIB_SCHDL_NOTI_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("ica_INVSTG_COMPLT_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_SECU_STAT_SUBMIT_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_SECU_STAT_EFCT_OCCR_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_LIST_COMITE_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_FOUND_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_ASSO_REG_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_SUBS_STRT_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("ibx_DFC_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("edt_SUBS_END_DD", "yyyyMMdd");
        $c.date.checkCalendarFormat("ibx_LIST_FORN_EXCH_LIST_DD1", "yyyyMMdd");
        $c.date.checkCalendarFormat("ibx_LIST_FORN_EXCH_LIST_DD2", "yyyyMMdd");

        btn_update.hide();
        btn_save.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05003.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description 법인선택 팝업
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_COM_NM_onclick = async function(e) {
    try {
        // if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "") {
        //     $c.win.alert("[유가증권]을 선택하세요.");
        //     return;
        // }
        // scwin.fn_GetPar = fn_GetParIsur;
        // scwin.fn_SetPar = fn_SetParIsur;
        // $c.lce.fn_PopFindExamCorp($c.stf.getObjectValue(cmb_SECUGRP_ID));

        const secugrpId = cmb_SECUGRP_ID.getValue()

        const url = "/ui/lst/common/ULDSTF05011.xml";
        let popTitle =  cmb_SECUGRP_ID.getText()+"법인 선택";

        const opts = {
            id: "ULDSTF05011",
            popupName: popTitle,
            width: 900,
            height: 700,
            frameModal: "top",
        };

        const popupData = {
            "secugrpId" : secugrpId,  
        }
        const res = await $c.win.openPopup(url, opts, popupData);
        if(res.isurCd !=="") {
            txb_ISUR_CD.setValue(res.isurCd) ; // 법인코드
            txb_COM_NM.setValue(res.comNm) ; // 법인명
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05003.img_COM_NM_onclick" });
    }
};

