    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05003.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        chk_WEB_DP_YN.setValue((dts_Item.NameString(1, "WEB_DP_YN") === "N"));

        chk_WEB_NOPN_YN.setValue((dts_Item.NameString(1, "WEB_NOPN_YN") === "Y"));
        if (scwin.vBzProcsNo === "") {

            buttonSet.setInsertStatus();
            scwin.initForm('C');
        } else {
            scwin.initForm('X');

            buttonSet.setUpdateStatus();
        }
        if (js_dep_cd !== '2520' && // 상장심사팀
            js_dep_cd !== '2540' && // 심사1팀,심사2팀
            js_dep_cd !== '2615') // 기업심사팀(2615) by nhkw

        {

            buttonSet.setErrorStatus(); // disable 시킨다.

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05003.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description trs_Save 트랜잭션 성공 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = function() {
    try {
        scwin.alertJobMsg('S');
        scwin.readSync();
        scwin.parentRefresh();
        if (buttonSet.status === "U") {

            const parentWin = $c.win.getParent();
            parentWin.dts_List.RowPosition = scwin.rowPos;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05003.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description trs_Save 트랜잭션 실패 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        scwin.alertJobMsg('F');
        $c.win.alert(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05003.trs_Save_OnFail" });
    }
};

