///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getMaintradeBank
 * @description 주거래은행코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getMaintradeBank = async function() {

    const sbmOptions = {
        id : "sbm_getMaintradeBank",
        method: "get",
        action : "/api/listing/common/code/list-maintrade-bank",
        target : "dlt_listMaintradeBankRes=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        dlt_listMaintradeBankRes.insertRow(0);
    }
}

/**
 * @method
 * @name searchCode
 * @description 코드 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {

    let param = dma_searchCdReq.getJSON()
    param.codeList = ["CURR_ISO_CD","EXT_AUDTR_CD","TRANSSTK_AGNT_CD"];

    const sbmOptions = {
        id : "sbm_codeList",
        action : "/api/listing/common/code/list-code-value",
        method : "get",
        target : "dlt_CurrIsoCdBox=body.CURR_ISO_CD, dlt_parvalCurrIsoCdBox=body.CURR_ISO_CD,"+
                 "dlt_fncCurrIsoCdBox=body.CURR_ISO_CD,  dlt_pubprcCurrIsoCdBox=body.CURR_ISO_CD, dlt_netincmCurrIsoCdBox=body.CURR_ISO_CD,"+
                 "dlt_pubprcSchdlCurrIsoCdBox=body.CURR_ISO_CD, dlt_extAudtrCdBox=body.EXT_AUDTR_CD, dlt_transstkAgntCdBox=body.TRANSSTK_AGNT_CD",
        isProcessMsg : false
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions,param);
    if (res.responseJSON.success === true) {

            dlt_netincmCurrIsoCdBox.insertRow(0);
            dlt_CurrIsoCdBox.insertRow(0);
            dlt_fncCurrIsoCdBox.insertRow(0);
            dlt_transstkAgntCdBox.insertRow(0);
            dlt_extAudtrCdBox.insertRow(0)

            cmb_TRANSSTK_AGNT_CD.setNodeSet("data:" + "dlt_transstkAgntCdBox","text","value");
            cmb_EXT_AUDTR_CD.setNodeSet("data:" + "dlt_extAudtrCdBox","text","value");
            cmb_NETINCM_CURR_ISO_CD.setNodeSet("data:" + "dlt_netincmCurrIsoCdBox","text","value");
            sbx_CURR_ISO_CD.setNodeSet("data:" + "dlt_CurrIsoCdBox","text","value");
            cmb_FNC_CURR_ISO_CD.setNodeSet("data:" + "dlt_fncCurrIsoCdBox","text","value");
            sbx_PUBPRC_CURR_ISO_CD.setNodeSet("data:" + "dlt_pubprcCurrIsoCdBox","text","value");
            sbx_PUBPRC_SCHDL_CURR_ISO_CD.setNodeSet("data:" + "dlt_pubprcSchdlCurrIsoCdBox","text","value");

            sbx_PUBPRC_CURR_ISO_CD.setSelectedIndex(8);
            sbx_PUBPRC_SCHDL_CURR_ISO_CD.setSelectedIndex(8);
    }

};

// scwin.setParIsur = function(arrPar) {
//     var dbClickYn = arrPar[0].DBCLICKYN;
//     if (dbClickYn == "Y") {
//         txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
