/**
 * @method
 * @name readSync
 * @description 상세조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {

    const params = {"bzProcsNo" : scwin.vBzProcsNo}
    const sbmOptions = {
        id : "sbm_issuance",
        method: "get",
        // ref: "dma_searchReq",
        action : "/api/listing/lstproc/stock/prelisting-kospi/select-one",
        target : "dma_prelistingKospiDetailRes=body",
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions,JSON.stringify(params));
    if (res.responseJSON.success) {
        let invstgProgStatCd = res.responseJSON.body.invstgProgStatCd;
        if (invstgProgStatCd !== "" && invstgProgStatCd.substring(0,1) !== '0') {
            cmb_INVSTG_PROG_STAT_CD.setNodeSet("data:" + "dlt_invstgProgStatCdBox2","text","value");
        } else {
            cmb_INVSTG_PROG_STAT_CD.setNodeSet("data:" + "dlt_invstgProgStatCdBox1","text","value");
        }
    }
//  scwin.changeForm(dts_Item.NameValue(1, "INVSTG_PROG_STAT_CD"));

};

