/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @returns {void}
 * @hidden N
 */
scwin.save = function() {
    scwin.TR_JOB = 'I';
    // TODO Stage2: 미정의 함수 scwin.fn_CheckForm — 원본은 ETN 공통 $c.en.fn_CheckForm(미반입, 주석 처리) 이므로 폼 검증 로직 결정 후 대체
    if (scwin.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_INSERT;*/

            X = TB_JOB_INSERT; /*ORG SRC: dts_Item.NameValue(1, "BZ_PROCS_NO") = vBzProcsNo;*/ X = scwin.vBzProcsNo;
            // $c.win.alert("BZ_PROCS_NO>>>>>>>> :"+dts_Item.NameValue(1,"BZ_PROCS_NO"));

            scwin.trs();
        }
    }
};

/**
 * @method
 * @name update
 * @description 입력값을 수정 저장한다.
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    scwin.TR_JOB = 'U';
    // TODO Stage2: 미정의 함수 scwin.fn_CheckForm — 원본은 ETN 공통 $c.en.fn_CheckForm(미반입, 주석 처리) 이므로 폼 검증 로직 결정 후 대체
    if (scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        scwin.trs();
    }
};

