/**
 * @method
 * @name prepare
 * @description 예비심사 절차등록 팝업
 * @returns {void}
 * @hidden N
 */
scwin.prepare = function() {

    const url = "/ui/lstproc/ULDSTF05237.xml";
    const popTitle = "예비심사관리 절차등록";

    const opts = {
        id: "ULDSTF05237",
        popupName: popTitle,
        width: 800,
        height: 900,
        type: "pageFramePopup",
    };

    const popData = {
        "gBzProcsNo" : scwin.vBzProcsNo 
    }

    $c.win.openPopup(url, opts, popData);

};

